INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370995, 15673, 'OpIndia', 'en', 'No azadi slogans, Hinduphobia, abuses or stone pelting: How Jharkhand student protests achieved success without going the CJP way', 'https://www.opindia.com/2026/08/no-azadi-slogans-abuses-or-stone-pelting-jharkhand-student-protests-succeeded-without-going-the-cjp-way', 'Following a 24-day agitation, the Jharkhand government cancelled the JSSC-CGL exam and ordered a CID probe into recruitment irregularities since 2014. However, protesting students have refused to call off their demonstration, demanding an independent investigation by the CBI.', 'https://www.opindia.com/wp-content/uploads/2026/08/Hemant-Soren.jpg', '2026-08-18T07:39:24+00:00', '2026-08-18T08:18:11.662546'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
