INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371304, 15673, 'The Economic Times', 'en', 'Jharkhand cancels JSSC-CGL exam: Devendra Nath Mahato, student leaders break hunger strike', 'https://news.google.?oc=5', 'Jharkhand cancels JSSC-CGL exam: Devendra Nath Mahato, student leaders break hunger strike economictimes.indiatimes.com', '', '2026-08-18T01:21:00+00:00', '2026-08-18T08:20:56.934146'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371657, 15673, 'The Times of India', 'en', 'JSSC-CGL exam cancellation ends one protest, sparks another as 2,000 fear job loss', 'https://timesofindia.indiatimes.com/india/tell-us-our-crime-jssc-cgl-exam-cancellation-ends-one-protest-sparks-another-as-2000-fear-job-loss/articleshow/133316120.cms', 'Successful JSSC-CGL candidates protested the Jharkhand government''s decision to cancel recruitment exams. They fear losing their government jobs after the cancellation announcement on Monday night. Protesters demanded a CBI probe and an opportunity to defend themselves against allegations. The government defended the cancellation to restore confidence in the recruitment system. Fresh vacancies will provide opportunities for deserving candidates after reforms.', 'https://static.toiimg.com/photo/msid-133316568,imgsize-226336.cms', '2026-08-18T08:31:17+00:00', '2026-08-18T09:12:45.896745'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
