INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372518, 15673, 'The Hindu', 'en', 'Protests continue even after Jharkhand cancels JSSC-CGL exam', 'https://www.thehindu.com/videos/protests-continue-even-after-jharkhand-cancels-jssc-cgl-exam/article71359800.ece', 'Despite the Jharkhand government cancelling the JSSC-CGL examination after 24 days of protests, the agitation continues as students demand a CBI probe into alleged irregularities. Meanwhile, candidates recruited through the examination have staged a dharna seeking clarity on their appointments.', 'https://th-i.thgim.com/public/videos/sulizo/article71359802.ece/alternates/LANDSCAPE_1200/_Jharkhand%201.png', '2026-08-18T09:39:53+00:00', '2026-08-18T10:03:58.792220'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
