INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (399159, 15674, 'Fortune', 'en', 'Forget AI, debt has become the main character on Wall Street as markets just now decided that it’s gotten out of control after years of warnings', 'https://fortune.com/2026/08/22/debt-tipping-point-bond-yields-treasury-selloff-inflation-dollar', '"When does debt become unsustainable? When the global financial markets say it is. That appears to be happening."', 'https://fortune.com/img-assets/wp-content/uploads/2026/08/GettyImages-2281407236-e1787420550291.jpg?w=2048', '2026-08-22T19:25:31+00:00', '2026-08-23T05:16:34.551920'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
