INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (368826, 15676, 'South China Morning Post', 'en', 'US transshipment ‘scam’ claims put Asean exporters in a bind', 'https://www.scmp.com/week-asia/politics/article/3364381/us-transshipment-scam-claims-put-asean-exporters-bind', 'Southeast Asian exporters may soon face a heavier burden of proof to show they are not helping Chinese goods dodge US tariffs after the White House named nine countries in the region as part of what it called a global “Shadow Transshipment Network”. The warning came in a White House report titled “The Great Transshipment Scam”, which alleged that Chinese-origin goods were being routed through lower-tariff jurisdictions and re-entering the US market under new national identities. Analysts said...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/7ffd50a4-e1eb-41b2-9d20-4e7e48cfa922_9129020e.jpg?itok=zv0kcwfi&v=1787030037', '2026-08-18T05:13:59+00:00', '2026-08-18T05:51:10.761785'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
